require_once __DIR__.'/../includes/verificar_sesion.php';$roles_permitidos=['administrador'];require_once __DIR__.'/../includes/verificar_rol.php';require_once __DIR__.'/../config/conexion.php';$q=$pdo->query('SELECT f.*,s.marca,s.modelo,u.nombre AS cliente,p.metodo_pago,p.estado AS estado_pago FROM facturas f JOIN solicitudes s ON s.id_solicitud=f.id_solicitud JOIN usuarios u ON u.id_usuario=s.id_cliente LEFT JOIN pagos p ON p.id_solicitud=f.id_solicitud ORDER BY f.fecha DESC');$facturas=$q->fetchAll();$titulo_pagina='Facturación';$ruta_base='../';require_once __DIR__.'/../includes/encabezado.php';
?><div class="cabecera-panel"><div><span class="etiqueta">REGISTRO INTERNO</span><h1>Facturación</h1><p>Control interno de servicios realizados. No es facturación fiscal.</p></div></div><section class="tabla-contenedor"><table class="tabla"><thead><tr><th>Número de servicio</th><th>Cliente</th><th>Servicio</th><th>Fecha</th><th>Subtotal</th><th>Refacciones</th><th>Total</th><th>Pago</th></tr></thead><tbody><?php if(!$facturas): ?><tr><td colspan="8" class="vacio">Todavía no hay facturas generadas.</td></tr><?php else: foreach($facturas as $f): ?><tr><td><strong><?= escapar($f['numero_servicio']) ?></strong></td><td><?= escapar($f['cliente']) ?></td><td><?= escapar($f['marca'].' '.$f['modelo']) ?></td><td><?= date('d/m/Y',strtotime($f['fecha'])) ?></td><td>$<?= number_format($f['subtotal'],2) ?></td><td>$<?= number_format($f['refacciones'],2) ?></td><td class="texto-verde">$<?= number_format($f['total'],2) ?></td><td><?= escapar($f['metodo_pago']??'—') ?><br><span class="<?= estado_clase($f['estado_pago']??'Pendiente') ?>"><?= escapar($f['estado_pago']??'Pendiente') ?></span></td></tr><?php endforeach; endif; ?></tbody></table></section><?php require_once __DIR__.'/../includes/pie.php'; ?>


